function randInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function pick(arr) {
    return arr[randInt(0, arr.length - 1)];
}

function randomString(length) {
    var chars = 'abcdefghijklmnopqrstuvwxyz';
    var s = '';
    for (var i = 0; i < length; i++) {
        s += chars[randInt(0, chars.length - 1)];
    }
    return s;
}

function randomFirstName() {
    var names = ['James', 'Mary', 'Robert', 'Patricia', 'John', 'Linda', 'Michael', 'Barbara', 'David', 'Elizabeth'];
    return pick(names) + '_' + randomString(5);
}

function randomLastName() {
    var names = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez'];
    return pick(names) + '_' + randomString(5);
}

function randomTotalPrice() {
    return randInt(10, 2000);
}

function randomDepositPaid() {
    return Math.random() < 0.5;
}

function pad(n) {
    return n < 10 ? '0' + n : '' + n;
}

// Возвращает дату в формате YYYY-MM-DD, смещённую от сегодняшней на случайное
// число дней в диапазоне [startOffsetDays, endOffsetDays].
function randomDate(startOffsetDays, endOffsetDays) {
    var base = new Date();
    var offset = randInt(startOffsetDays, endOffsetDays);
    base.setDate(base.getDate() + offset);
    return base.getFullYear() + '-' + pad(base.getMonth() + 1) + '-' + pad(base.getDate());
}

function randomBookingDates() {
    var checkin = randomDate(1, 30);
    var checkout = randomDate(31, 90);
    return { checkin: checkin, checkout: checkout };
}

function randomAdditionalNeeds() {
    return pick(['Breakfast', 'Dinner', 'Lunch', 'Late checkout', 'Extra towels', 'Parking']);
}

function randomInvalidToken() {
    return randomString(15) + randomString(5);
}

function randomBigId() {
    return randInt(900000000000, 999999999999);
}

// Строит динамическое валидное тело Booking со случайными данными.
// overrides позволяет подменить/удалить конкретные поля под конкретный тест-кейс:
//   { field: VALUE }        -> заменить значение поля
//   { field: 'DELETE_FIELD__' }   -> удалить поле целиком
//   { bookingdates: {...} } -> примешать/удалить вложенные поля checkin/checkout
function buildBookingObject(overrides) {
    var dates = randomBookingDates();
    var obj = {
        firstname: randomFirstName(),
        lastname: randomLastName(),
        totalprice: randomTotalPrice(),
        depositpaid: randomDepositPaid(),
        bookingdates: { checkin: dates.checkin, checkout: dates.checkout },
        additionalneeds: randomAdditionalNeeds()
    };
    if (overrides) {
        Object.keys(overrides).forEach(function (key) {
            if (overrides[key] === 'DELETE_FIELD__') {
                delete obj[key];
            } else if (key === 'bookingdates' && typeof overrides[key] === 'object' && overrides[key] !== null) {
                var merged = Object.assign({}, obj.bookingdates);
                Object.keys(overrides[key]).forEach(function (subKey) {
                    if (overrides[key][subKey] === 'DELETE_FIELD__') {
                        delete merged[subKey];
                    } else {
                        merged[subKey] = overrides[key][subKey];
                    }
                });
                obj.bookingdates = merged;
            } else {
                obj[key] = overrides[key];
            }
        });
    }
    return obj;
}

function buildBookingXml(obj) {
    var xml = '<booking>\n';
    xml += '  <firstname>' + obj.firstname + '</firstname>\n';
    xml += '  <lastname>' + obj.lastname + '</lastname>\n';
    xml += '  <totalprice>' + obj.totalprice + '</totalprice>\n';
    xml += '  <depositpaid>' + obj.depositpaid + '</depositpaid>\n';
    xml += '  <bookingdates>\n';
    xml += '    <checkin>' + obj.bookingdates.checkin + '</checkin>\n';
    xml += '    <checkout>' + obj.bookingdates.checkout + '</checkout>\n';
    xml += '  </bookingdates>\n';
    if (obj.additionalneeds !== undefined) {
        xml += '  <additionalneeds>' + obj.additionalneeds + '</additionalneeds>\n';
    }
    xml += '</booking>';
    return xml;
}

// pm.sendRequest возвращает Promise, если не передан callback.
function sendRequestAsync(requestConfig) {
    return pm.sendRequest(requestConfig);
}

// Получает НОВЫЙ токен при каждом вызове.
function getFreshToken(username, password) {
    return sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/auth',
        method: 'POST',
        header: { 'Content-Type': 'application/json' },
        body: {
            mode: 'raw',
            raw: JSON.stringify({
                username: username || pm.collectionVariables.get('validUsername'),
                password: password || pm.collectionVariables.get('validPassword')
            })
        }
    }).then(function (res) {
        var json = res.json();
        return json.token;
    });
}

// Создаёт НОВУЮ запись booking при каждом вызове .
function createFreshBooking(overrides) {
    var bodyObj = buildBookingObject(overrides);
    return sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking',
        method: 'POST',
        header: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify(bodyObj) }
    }).then(function (res) {
        var json = res.json();
        return { id: json.bookingid, body: bodyObj, response: res, raw: json };
    });
}

(async function () {
    // TC1: валидные username/password -> 200 OK (ответ основного запроса)
    pm.test('Запрос POST на эндпоинт /auth с валидными username и password в body возвращает ответ 200 OK', function () {
        pm.response.to.have.status(200);
    });

    // TC2: тело ответа содержит токен
    pm.test('Запрос POST на эндпоинт /auth с валидными username и password в body возвращает тело ответа с токеном в формате json: {"token": "…......"}', function () {
        var json = pm.response.json();
        pm.expect(json).to.have.property('token');
        pm.expect(json.token).to.be.a('string').and.not.empty;
    });

    // TC3 и TC4: запрос без body
    var resNoBody = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/auth',
        method: 'POST',
        header: { 'Content-Type': 'application/json' }
    });
    pm.test('Запрос POST на эндпоинт /auth без body возвращает ответ 401 Unauthorized', function () {
        pm.expect(resNoBody.code).to.eql(401);
    });
    pm.test('Запрос POST на эндпоинт /auth без body возвращает тело ответа {"reason": "Bad credentials"}', function () {
        pm.expect(resNoBody.json()).to.eql({ reason: 'Bad credentials' });
    });

    // TC5 и TC6: пустой username
    var resEmptyUser = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/auth',
        method: 'POST',
        header: { 'Content-Type': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify({ username: '', password: pm.collectionVariables.get('validPassword') }) }
    });
    pm.test('Запрос POST на эндпоинт /auth с пустым значением параметра username в body возвращает ответ 401 Unauthorized', function () {
        pm.expect(resEmptyUser.code).to.eql(401);
    });
    pm.test('Запрос POST на эндпоинт /auth с пустым значением параметра username в body возвращает тело ответа {"reason": "Bad credentials"}', function () {
        pm.expect(resEmptyUser.json()).to.eql({ reason: 'Bad credentials' });
    });

    // TC7 и TC8: невалидный username
    var resBadUser = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/auth',
        method: 'POST',
        header: { 'Content-Type': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify({ username: 'adminerror', password: pm.collectionVariables.get('validPassword') }) }
    });
    pm.test('Запрос POST на эндпоинт /auth с невалидным значением параметра username в body возвращает ответ 401 Unauthorized', function () {
        pm.expect(resBadUser.code).to.eql(401);
    });
    pm.test('Запрос POST на эндпоинт /auth с невалидным значением параметра username в body возвращает тело ответа {"reason": "Bad credentials"}', function () {
        pm.expect(resBadUser.json()).to.eql({ reason: 'Bad credentials' });
    });

    // TC9 и TC10: пустой password
    var resEmptyPass = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/auth',
        method: 'POST',
        header: { 'Content-Type': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify({ username: pm.collectionVariables.get('validUsername'), password: '' }) }
    });
    pm.test('Запрос POST на эндпоинт /auth с пустым значением параметра password в body возвращает ответ 401 Unauthorized', function () {
        pm.expect(resEmptyPass.code).to.eql(401);
    });
    pm.test('Запрос POST на эндпоинт /auth с пустым значением параметра password в body возвращает тело ответа {"reason": "Bad credentials"}', function () {
        pm.expect(resEmptyPass.json()).to.eql({ reason: 'Bad credentials' });
    });

    // TC11 и TC12: невалидный password
    var resBadPass = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/auth',
        method: 'POST',
        header: { 'Content-Type': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify({ username: pm.collectionVariables.get('validUsername'), password: 'passworderror' }) }
    });
    pm.test('Запрос POST на эндпоинт /auth с невалидным значением параметра password в body возвращает ответ 401 Unauthorized', function () {
        pm.expect(resBadPass.code).to.eql(401);
    });
    pm.test('Запрос POST на эндпоинт /auth с невалидным значением параметра password в body возвращает тело ответа {"reason": "Bad credentials"}', function () {
        pm.expect(resBadPass.json()).to.eql({ reason: 'Bad credentials' });
    });
})();

// TC13: валидные username/password, но запрос отправлен по HTTP (не HTTPS).
pm.test('Запрос POST на эндпоинт /auth с валидными username и password в body по протоколу HTTP (не HTTPS) возвращает ответ 400 Bad request без токена в теле ответа', function () {
    pm.expect(pm.response.code).to.eql(400);
    pm.expect(pm.response.text()).to.not.include('token');
});

