(async function () {
    // TC15: валидный JSON -> 201 Created (ответ основного запроса)
    pm.test('Запрос Post на эндпоинт /booking с валидным JSON в Body возвращает ответ 201 Created', function () {
        pm.response.to.have.status(201);
    });

    // TC16: тело ответа соответствует JSON-схеме
    var bookingResponseSchema = {
        type: 'object',
        properties: {
            bookingid: { type: 'integer' },
            booking: {
                type: 'object',
                properties: {
                    firstname: { type: 'string' },
                    lastname: { type: 'string' },
                    totalprice: { type: 'integer' },
                    depositpaid: { type: 'boolean' },
                    bookingdates: {
                        type: 'object',
                        properties: {
                            checkin: { type: 'string' },
                            checkout: { type: 'string' }
                        },
                        required: ['checkin', 'checkout']
                    },
                    additionalneeds: { type: 'string' }
                },
                required: ['firstname', 'lastname', 'totalprice', 'depositpaid', 'bookingdates']
            }
        },
        required: ['bookingid', 'booking']
    };
    pm.test('Запрос Post на эндпоинт /booking с валидным JSON в Body возвращает в теле ответа JSON, соответствующий схеме: см. Description', function () {
        pm.response.to.have.jsonSchema(bookingResponseSchema);
    });

    // TC14: валидный XML в body -> 201 Created
    var xmlBodyObj = buildBookingObject();
    var resXml = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking',
        method: 'POST',
        header: { 'Content-Type': 'application/xml', 'Accept': 'application/xml' },
        body: { mode: 'raw', raw: buildBookingXml(xmlBodyObj) }
