}

function pick(arr) {
    return arr[randInt(0, arr.length - 1)];
}

function randomString(length) {
    var chars = 'abcdefghijklmnopqrstuvwxyz';
    var s = '';
    for (var i = 0; i < length; i++) {
        s += chars[randInt(0, chars.length - 1)];
    }
    return s;
}

function randomFirstName() {
