    pm.test('При запросе Put на эндпоинт /booking/id, где id = id из созданной предварительно записи, с валидным JSON в теле запроса возвращается код 200 OK', function () {
        pm.response.to.have.status(200);
    });

    // TC46: тело ответа содержит изменённые данные из запроса
    pm.test('При запросе Put на эндпоинт /booking/id с валидным id, с валидным JSON в body возвращается тело ответа, в котором указан измененный JSON с данными из тела запроса', function () {
        var sentBody = JSON.parse(pm.variables.get('putBodyJson'));
        pm.expect(pm.response.json()).to.eql(sentBody);
    });

    // TC47: без токена -> 403 (своя новая запись)
    var createdNoToken = await createFreshBooking();
    var resNoToken = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking/' + createdNoToken.id,
        method: 'PUT',
        header: { 'Content-Type': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify(buildBookingObject()) }
    });
    pm.test('При запросе Put на эндпоинт /booking/id с валидным id, с валидным JSON в body БЕЗ токена возвращается ответ с кодом 403 Forbidden', function () {
        pm.expect(resNoToken.code).to.eql(403);
    });

    // TC48: невалидный токен -> 403 (своя новая запись)
    var createdBadToken = await createFreshBooking();
    var resBadToken = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking/' + createdBadToken.id,
        method: 'PUT',
        header: { 'Content-Type': 'application/json', Cookie: 'token=' + randomInvalidToken() },
        body: { mode: 'raw', raw: JSON.stringify(buildBookingObject()) }
    });
    pm.test('При запросе Put на эндпоинт /booking/id с валидным id, с валидным JSON в body с невалидным токененом возвращается ответ с кодом 403 Forbidden', function () {
        pm.expect(resBadToken.code).to.eql(403);
    });

    // PUT с заведомо невалидным (неполным) телом -> ожидаем 400. Токен и запись -- свои на каждый вызов.
    async function expectInvalidUpdate(summary, overrides) {
        var token = await getFreshToken();
        var created = await createFreshBooking();
        var res = await sendRequestAsync({
            url: pm.collectionVariables.get('baseUrl') + '/booking/' + created.id,
            method: 'PUT',
            header: { 'Content-Type': 'application/json', Cookie: 'token=' + token },
            body: { mode: 'raw', raw: JSON.stringify(buildBookingObject(overrides)) }
        });
        pm.test(summary, function () {
            pm.expect(res.code).to.eql(400);
        });
    }

    await expectInvalidUpdate('При запросе Put на эндпоинт /booking/id с валидным id, но с НЕвалидным JSON (отсутсвует lastname) возвращается ответ с кодом 400 Bad request', { lastname: 'DELETE_FIELD__' });
    await expectInvalidUpdate('При запросе Put на эндпоинт /booking/id с валидным id, но с НЕвалидным JSON (отсутсвует totalprice) возвращается ответ с кодом 400 Bad request', { totalprice: 'DELETE_FIELD__' });
    await expectInvalidUpdate('При запросе Put на эндпоинт /booking/id с валидным id, но с НЕвалидным JSON (отсутсвует depositpaid) возвращается ответ с кодом 400 Bad request', { depositpaid: 'DELETE_FIELD__' });
    await expectInvalidUpdate('При запросе Put на эндпоинт /booking/id с валидным id, но с НЕвалидным JSON (отсутсвует checkin) возвращается ответ с кодом 400 Bad request', { bookingdates: { checkin: 'DELETE_FIELD__' } });
    await expectInvalidUpdate('При запросе Put на эндпоинт /booking/id с валидным id, но с НЕвалидным JSON (отсутсвует checkout) возвращается ответ с кодом 400 Bad request', { bookingdates: { checkout: 'DELETE_FIELD__' } });

    // TC54: невалидный (несуществующий) id -> 400
    var tokenTc54 = await getFreshToken();
    var resInvalidId = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking/' + randomBigId(),
        method: 'PUT',
        header: { 'Content-Type': 'application/json', Cookie: 'token=' + tokenTc54 },
        body: { mode: 'raw', raw: JSON.stringify(buildBookingObject()) }
    });
    pm.test('При запросе Put на эндпоинт /booking/id с НЕвалидным id возвращается ответ с кодом 400 Bad request', function () {
        pm.expect(resInvalidId.code).to.eql(400);
    });
})();

// ========================= ОБЩИЕ ХЕЛПЕРЫ (Collection Pre-request Script) =========================
// Эти функции доступны в Pre-request script и Tests script КАЖДОГО запроса,
// так как Postman выполняет их в одном JS-контексте для одного вызова запроса.

function randInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function pick(arr) {
    return arr[randInt(0, arr.length - 1)];
}

function randomString(length) {
    var chars = 'abcdefghijklmnopqrstuvwxyz';
    var s = '';
    for (var i = 0; i < length; i++) {
        s += chars[randInt(0, chars.length - 1)];
    }
    return s;
}

function randomFirstName() {
    var names = ['James', 'Mary', 'Robert', 'Patricia', 'John', 'Linda', 'Michael', 'Barbara', 'David', 'Elizabeth'];
    return pick(names) + '_' + randomString(5);
}

function randomLastName() {
    var names = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez'];
    return pick(names) + '_' + randomString(5);
}

function randomTotalPrice() {
    return randInt(10, 2000);
}

function randomDepositPaid() {
    return Math.random() < 0.5;
}

function pad(n) {
    return n < 10 ? '0' + n : '' + n;
}

// Возвращает дату в формате YYYY-MM-DD, смещённую от сегодняшней на случайное
// число дней в диапазоне [startOffsetDays, endOffsetDays].
function randomDate(startOffsetDays, endOffsetDays) {
    var base = new Date();
    var offset = randInt(startOffsetDays, endOffsetDays);
    base.setDate(base.getDate() + offset);
    return base.getFullYear() + '-' + pad(base.getMonth() + 1) + '-' + pad(base.getDate());
}

function randomBookingDates() {
    var checkin = randomDate(1, 30);
    var checkout = randomDate(31, 90);
    return { checkin: checkin, checkout: checkout };
}

function randomAdditionalNeeds() {
    return pick(['Breakfast', 'Dinner', 'Lunch', 'Late checkout', 'Extra towels', 'Parking']);
}

function randomInvalidToken() {
    return randomString(15) + randomString(5);
}

function randomBigId() {
    return randInt(900000000000, 999999999999);
}

// Строит динамическое валидное тело Booking со случайными данными.
// overrides позволяет подменить/удалить конкретные поля под конкретный тест-кейс:
//   { field: VALUE }        -> заменить значение поля
//   { field: 'DELETE_FIELD__' }   -> удалить поле целиком
//   { bookingdates: {...} } -> примешать/удалить вложенные поля checkin/checkout
function buildBookingObject(overrides) {
    var dates = randomBookingDates();
    var obj = {
        firstname: randomFirstName(),
        lastname: randomLastName(),
        totalprice: randomTotalPrice(),
        depositpaid: randomDepositPaid(),
        bookingdates: { checkin: dates.checkin, checkout: dates.checkout },
        additionalneeds: randomAdditionalNeeds()
    };
    if (overrides) {
        Object.keys(overrides).forEach(function (key) {
            if (overrides[key] === 'DELETE_FIELD__') {
                delete obj[key];
            } else if (key === 'bookingdates' && typeof overrides[key] === 'object' && overrides[key] !== null) {
                var merged = Object.assign({}, obj.bookingdates);
                Object.keys(overrides[key]).forEach(function (subKey) {
                    if (overrides[key][subKey] === 'DELETE_FIELD__') {
                        delete merged[subKey];
                    } else {
                        merged[subKey] = overrides[key][subKey];
                    }
                });
                obj.bookingdates = merged;
            } else {
                obj[key] = overrides[key];
            }
        });
    }
    return obj;
}

function buildBookingXml(obj) {
    var xml = '<booking>\n';
    xml += '  <firstname>' + obj.firstname + '</firstname>\n';
    xml += '  <lastname>' + obj.lastname + '</lastname>\n';
    xml += '  <totalprice>' + obj.totalprice + '</totalprice>\n';
    xml += '  <depositpaid>' + obj.depositpaid + '</depositpaid>\n';
    xml += '  <bookingdates>\n';
    xml += '    <checkin>' + obj.bookingdates.checkin + '</checkin>\n';
    xml += '    <checkout>' + obj.bookingdates.checkout + '</checkout>\n';
    xml += '  </bookingdates>\n';
    if (obj.additionalneeds !== undefined) {
        xml += '  <additionalneeds>' + obj.additionalneeds + '</additionalneeds>\n';
    }
    xml += '</booking>';
    return xml;
}

// pm.sendRequest возвращает Promise, если не передан callback (Postman v10+).
function sendRequestAsync(requestConfig) {
    return pm.sendRequest(requestConfig);
}

// Получает НОВЫЙ токен при каждом вызове (требование независимости тестов).
function getFreshToken(username, password) {
    return sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/auth',
        method: 'POST',
        header: { 'Content-Type': 'application/json' },
        body: {
            mode: 'raw',
            raw: JSON.stringify({
                username: username || pm.collectionVariables.get('validUsername'),
                password: password || pm.collectionVariables.get('validPassword')
            })
        }
    }).then(function (res) {
        var json = res.json();
        return json.token;
    });
}

// Создаёт НОВУЮ запись booking при каждом вызове (требование независимости тестов).
function createFreshBooking(overrides) {
    var bodyObj = buildBookingObject(overrides);
    return sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking',
        method: 'POST',
        header: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: { mode: 'raw', raw: JSON.stringify(bodyObj) }
    }).then(function (res) {
        var json = res.json();
        return { id: json.bookingid, body: bodyObj, response: res, raw: json };
    });
}

// Предусловие TC55: получить токен, создать новую запись booking, подготовить полное тело обновления.
(async function () {
    try {
        var token = await getFreshToken();
        var created = await createFreshBooking();
        var fullPatchBody = buildBookingObject();
        pm.variables.set('patchToken', token);
        pm.variables.set('patchBookingId', created.id);
        pm.variables.set('patchBodyJson', JSON.stringify(fullPatchBody, null, 4));
    } catch (e) {
        console.log('[PartialUpdateBooking pre-request] Ошибка подготовки: ' + e.message);
    }
})();

