(async function () {
    // TC55: полное обновление всех полей -> 200, тело ответа содержит все изменённые параметры
    pm.test('При запросе Patch на эндпоинт /booking/id с валидным id, со всеми параметрами записи booking в JSON в body возвращается ответ 200 и запись в теле ответа со всеми измененными параметрами записи', function () {
        pm.response.to.have.status(200);
        var sentBody = JSON.parse(pm.variables.get('patchBodyJson'));
        pm.expect(pm.response.json()).to.eql(sentBody);
    });

    // Хелпер: частичное обновление одного поля. Токен и запись - свои на каждый вызов.
    async function expectPartialUpdate(summary, fieldName, value, checkFn) {
        var token = await getFreshToken();
        var created = await createFreshBooking();
        var body = {};
        body[fieldName] = value;
        var res = await sendRequestAsync({
            url: pm.collectionVariables.get('baseUrl') + '/booking/' + created.id,
            method: 'PATCH',
            header: { 'Content-Type': 'application/json', Cookie: 'token=' + token },
            body: { mode: 'raw', raw: JSON.stringify(body) }
        });
        pm.test(summary, function () {
            pm.expect(res.code).to.eql(200);
            checkFn(res.json());
        });
    }

    // TC56
    var newFirstname = randomFirstName();
    await expectPartialUpdate('При запросе Patch на эндпоинт /booking/id с валидным id, только с параметром firstname в JSON в body возвращается ответ 200 и запись в теле ответа, где значение firstname изменено', 'firstname', newFirstname, function (json) {
        pm.expect(json.firstname).to.eql(newFirstname);
    });

    // TC57
    var newLastname = randomLastName();
    await expectPartialUpdate('При запросе Patch на эндпоинт /booking/id с валидным id, только с параметром lastname в JSON в body возвращается ответ 200 и запись в теле ответа, где значение lastname изменено', 'lastname', newLastname, function (json) {
        pm.expect(json.lastname).to.eql(newLastname);
    });

    // TC58
    var newPrice = randomTotalPrice();
    await expectPartialUpdate('При запросе Patch на эндпоинт /booking/id с валидным id, только с параметром totalprice в JSON в body возвращается ответ 200 и запись в теле ответа, где значение totalprice изменено', 'totalprice', newPrice, function (json) {
        pm.expect(json.totalprice).to.eql(newPrice);
    });

    // TC59
    var newDeposit = randomDepositPaid();
    await expectPartialUpdate('При запросе Patch на эндпоинт /booking/id с валидным id, только с параметром depositpaid в JSON в body возвращается ответ 200 и запись в теле ответа, где значение depositpaid изменено', 'depositpaid', newDeposit, function (json) {
        pm.expect(json.depositpaid).to.eql(newDeposit);
    });

    // TC60
    var newDates = randomBookingDates();
    await expectPartialUpdate('При запросе Patch на эндпоинт /booking/id с валидным id, только с параметром bookingdates в JSON в body возвращается ответ 200 и запись в теле ответа, где значение bookingdates изменено', 'bookingdates', newDates, function (json) {
        pm.expect(json.bookingdates.checkin).to.eql(newDates.checkin);
        pm.expect(json.bookingdates.checkout).to.eql(newDates.checkout);
    });

    // TC61
    var newNeeds = randomAdditionalNeeds();
    await expectPartialUpdate('При запросе Patch на эндпоинт /booking/id с валидным id, только с параметром additionalneeds в JSON в body возвращается ответ 200 и запись в теле ответа, где значение additionalneeds изменено', 'additionalneeds', newNeeds, function (json) {
        pm.expect(json.additionalneeds).to.eql(newNeeds);
    });

    // TC62: невалидный (несуществующий) id -> 400
    var tokenTc62 = await getFreshToken();
    var resInvalidId = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking/' + randomBigId(),
        method: 'PATCH',
        header: { 'Content-Type': 'application/json', Cookie: 'token=' + tokenTc62 },
        body: { mode: 'raw', raw: JSON.stringify({ firstname: randomFirstName() }) }
    });
    pm.test('При запросе Patch на эндпоинт /booking/id с НЕвалидным id возвращается ответ с кодом 400 Bad request', function () {
        pm.expect(resInvalidId.code).to.eql(400);
    });

    // TC63: несуществующий параметр в body -> 400
    var tokenTc63 = await getFreshToken();
    var createdTc63 = await createFreshBooking();
    var resUnknownParam = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking/' + createdTc63.id,
        method: 'PATCH',
        header: { 'Content-Type': 'application/json', Cookie: 'token=' + tokenTc63 },
        body: { mode: 'raw', raw: JSON.stringify({ 'Wrong param': 'Value' }) }
    });
    pm.test('При запросе Patch на эндпоинт /booking/id с валидным id, с несуществующим параметром в JSON в body возвращается ответ 400 Bad request', function () {
        pm.expect(resUnknownParam.code).to.eql(400);
    });

    // TC64: без токена -> 403
    var createdTc64 = await createFreshBooking();
    var resNoToken = await sendRequestAsync({
        url: pm.collectionVariables.get('baseUrl') + '/booking/' + createdTc64.id,
        method: 'PATCH',
        header: { 'Content-Type': 'application/json' },
