        body: { mode: 'raw', raw: JSON.stringify({ firstname: randomFirstName() }) }
    });
    pm.test('При запросе Patch на эндпоинт /booking/id с валидным id, с валидным JSON в body, но с невалидным токеном возвращается ответ с кодом 403 Forbidden', function () {
        pm.expect(resBadToken.code).to.eql(403);
    });
})();
